const username = $json.body.erp_username;
const password = $json.body.erp_password;

// Open ERP login page
await $page.goto(
  'https://meta-digitrading.lhike-erp.com/home',
  {
    waitUntil: 'networkidle2',
    timeout: 60000
  }
);

// Wait for login form
await $page.waitForSelector('input[name="txtusername"]', {
  timeout: 30000
});

// Fill credentials
await $page.type('input[name="txtusername"]', username, {
  delay: 50
});

await $page.type('input[name="txtpass"]', password, {
  delay: 50
});

// Submit login form
await Promise.all([
  $page.click('button[type="submit"]'),
  $page.waitForNavigation({
    waitUntil: 'networkidle2',
    timeout: 60000
  }).catch(() => null)
]);

// Check for login error
const loginError = await $page.$('.alert-danger');

if (loginError) {
  const errorText = await $page.evaluate(
    el => el.textContent.trim(),
    loginError
  );

  throw new Error(`Login failed: ${errorText}`);
}

// Optional: verify login succeeded
const currentUrl = $page.url();

if (currentUrl.includes('/login')) {
  throw new Error('Login may have failed. Still on login page.');
}

// Get cookies
const cookies = await $page.cookies();

return [
  {
    json: {
      success: true,
      currentUrl,
      cookies
    }
  }
];

const { cookies, date, keyword } = $json;

const startDate = date;
const endDate = date;

await $page.setCookie(...cookies);

await $page.goto('https://meta-digitrading.lhike-erp.com/inventorytransactionhistory', { waitUntil: 'networkidle2', timeout: 60000 });

await $page.type(
  'input#sdate',
  startDate,
  { delay: 50 }
);

await $page.type(
  'input#edate',
  endDate,
  { delay: 50 }
);

await $page.type(
  'input#itemname',
  keyword,
  { delay: 50 }
);

await $page.click('a#btndtsearch')


await $page.waitForNetworkIdle({
  idleTime: 500,      // ms with no network requests
  timeout: 50000
});

async function extractTable($page) {
  return await $page.evaluate(() => {
    const table = document.querySelector('table');
    if (!table) return [];

    const headers = Array.from(table.querySelectorAll('thead th'))
      .map(th => th.innerText.trim());

    const rows = Array.from(table.querySelectorAll('tbody tr'));

    return rows.map(tr => {
      const cells = Array.from(tr.querySelectorAll('td')).map(td => td.innerText.trim());
      return Object.fromEntries(headers.map((h, i) => [h || `col_${i}`, cells[i] ?? '']));
    });
  });
}

async function isNextDisabled($page) {
  return await $page.evaluate(() => {
    const nextLi = document.querySelector('li.next');
    return !nextLi || nextLi.classList.contains('disabled');
  });
}

async function clickNext($page) {
  await $page.click('li.next a');
}

const all = [];
const seen = new Set();

await $page.waitForSelector('table');
await $page.waitForSelector('li.next');

while (true) {
  const pageRows = await extractTable($page);

  for (const r of pageRows) {
    const key = r['No'] ?? JSON.stringify(r);
    if (!seen.has(key)) {
      seen.add(key);
      all.push(r);
    }
  }

  if (await isNextDisabled($page)) break;

  // signature of current page so we can detect change
  const firstRowSig = await $page.evaluate(() => {
    const first = document.querySelector('table tbody tr');
    return first ? first.innerText.trim() : '';
  });

  await clickNext($page);

  // wait until table updates
  await $page.waitForFunction(
    (prev) => {
      const first = document.querySelector('table tbody tr');
      const now = first ? first.innerText.trim() : '';
      return now && now !== prev;
    },
    {},
    firstRowSig
  );
}


return all.reverse(); // (n8n) or console.log(all)

