return items
  .filter(item => {
    const input = item.json;

    return input["No"] != "No data available in table";
  })
  .map((item) => {
  const input = item.json;

  const goodsPO = input['In/Out - Goods (PO)'] ?? "0";
  const damageRTS = input['In - Damage (RTS)'] ?? "0";
  const goodsRTS = input['In/Out - Goods (RTS)'] ?? "0";
  const type = input.Type ?? "";

  const date = new Date(input['Transaction Date']);
  const formatted = date.toISOString().split('T')[0];

  const qty_in  = type === "OUT" ? "0" : String(goodsPO);
  const qty_out = type === "OUT" ? String(goodsPO) : "0";
  const rts_goods_in  = type === "OUT" ? "0" : String(goodsRTS);
  const rts_goods_out = type === "OUT" ? String(goodsRTS) : "0";

  // keep only non-empty original fields (drops Action, col_11..col_20, Search, etc.)
  const cleaned = Object.fromEntries(
    Object.entries(input).filter(([, v]) => v !== "" && v !== null && v !== undefined)
  );

  const remaining = input['Remaining Qty'] ?? 0;

  return {
    json: {
      date: formatted,
      ref_no: input["Transact By"] ?? "",
      po_qty_in: qty_in,
      po_qty_out: qty_out,
      rts_goods_in,
      rts_goods_out,
      rts_bad: damageRTS,
      inventory_remaining_stock: remaining, 
    },
  };
});

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.cookies = $input.first().json.cookies;
  item.json.keyword = $('Webhook').first().json.body.keyword;
  item.json.date = $('Webhook').first().json.body.date;
}

return $input.all();
